window.__finlexDocLoaded(211,{"id":211,"articles":[{"id":5418,"no":"问1","heading":"问：汽车销售企业在日常活动中购进并用于销售的二手车，应当如何进行会计处理？","text":"【发布日期：2023-01-03】\n答：按照《企业会计准则第1号——存货》（财会〔2006〕3号）等相关规定，存货，是指企业在日常活动中持有以备出售的产成品或商品、处在生产过程中的在产品、在生产过程或提供劳务过程中耗用的材料和物料等。存货同时满足下列条件的，才能予以确认：（一）与该存货有关的经济利益很可能流入企业；（二）该存货的成本能够可靠地计量。因此，本问题中的汽车销售企业在日常活动中购进并用于销售的二手车，应当作为存货进行会计处理，通过“库存商品”等科目进行核算。","seq":0}]});
